var p=UnityEngine.Object.FindAnyObjectByType<CampusRift.CampusExplorer>();var s=p.GetComponent<CampusRift.Skills.GiantHandSkill>();var hud=UnityEngine.Object.FindAnyObjectByType<CampusRift.UI.GameplayHUD>();
var health=p.GetComponents<CampusRift.Monsters.PlayerMonsterHealth>();var config=s.config;
return new{scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,dirty=UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty,healthCount=health.Length,hudUsesFirstHealth=hud.Health.Source==health[0],healthSettings=health.Select(h=>new{h.maxHealth,h.respawnOnDefeat,h.showLegacyHUD,id=h.GetEntityId().ToString()}).ToArray(),hudSource=hud.Health.Source?.GetEntityId().ToString(),radius=config.radius,cooldown=config.cooldown,meshTriangles=config.handMesh.triangles.Length/3,handShader=config.handMaterial.shader.isSupported,sigilShader=config.sigilMaterial.shader.isSupported,skillComponents=p.GetComponents<CampusRift.Skills.GiantHandSkill>().Length,slotKey=hud.Skills.GetSlot(1).KeyLabel.text};
